head.script:
/**
 * 상위 작업구분별 작업대상 마스터 코드 데이터
 */
scwin.targetCodeMaster = [
    { workType: "EQ", id: "EQ_A01", name: "압출 성형기 1호" },
    { workType: "EQ", id: "EQ_B01", name: "고속 정밀 냉각기" },
    { workType: "EQ", id: "EQ_C01", name: "자동 포장기 3호" },
    { workType: "EQ", id: "EQ_D01", name: "원료 배합기 2호" },
    { workType: "MAT", id: "IN_NORMAL", name: "정상입고" },
    { workType: "MAT", id: "IN_URGENT", name: "긴급입고" },
    { workType: "MAT", id: "OUT_NORMAL", name: "정상출고" },
    { workType: "MAT", id: "OUT_DISCARD", name: "폐기출고" }
];

/**
 * 특정일자별 샘플 작업내용 데이터 (서버 DB 조회 결과 대체용 데이터)
 */
scwin.workHistoryData = {
    "2026-09-07": [
        { "workType": "EQ", "workTarget": "EQ_A01,EQ_D01", "startTime": "08:00", "endTime": "11:30", "remark": "압출 1호기 점검 및 원료 배합" },
        { "workType": "MAT", "workTarget": "IN_URGENT", "startTime": "11:30", "endTime": "13:00", "remark": "원자재 긴급 입고" },
        { "workType": "ETC", "workTarget": "안전 교육 및 라인 청소", "startTime": "13:00", "endTime": "14:00", "remark": "주간 정기 청소" },
        { "workType": "EQ", "workTarget": "EQ_C01", "startTime": "14:00", "endTime": "17:00", "remark": "자동 포장기 3호 라인 교체" }
    ],
    "2026-09-06": [
        { "workType": "EQ", "workTarget": "EQ_B01", "startTime": "09:00", "endTime": "12:00", "remark": "고속 정밀 냉각기 정기 점검" },
        { "workType": "MAT", "workTarget": "OUT_NORMAL", "startTime": "13:30", "endTime": "16:00", "remark": "완제품 정상 출고" }
    ]
};

scwin.onpageload = function() {
    // WebSquare 4 / 5 호환성을 위한 방어적 폴백 헬퍼 등록
    if (window.grd_workList && typeof grd_workList.setCellItemList !== "function") {
        grd_workList.setCellItemList = function(rowIndex, colIndex, itemList) {
            if (typeof this.setCellItem === "function") {
                this.setCellItem(rowIndex, colIndex, itemList);
            } else if (typeof this.setColumnNodeSet === "function") {
                this.setColumnNodeSet(colIndex, itemList, "label", "value");
            } else if (typeof this.setCellNodeSet === "function") {
                this.setCellNodeSet(rowIndex, colIndex, itemList);
            }
        };
    }

    // [서버 DB 조회 시] Submission 실행 예시:
    // $w.executeSubmission("sbm_getTargetCodeMaster");

    // 테스트용 초기 샘플 데이터 세팅
    var sampleData = [
        { "workType": "EQ", "workTarget": "EQ_A01,EQ_C01", "startTime": "09:00", "endTime": "12:00" },
        { "workType": "MAT", "workTarget": "IN_NORMAL", "startTime": "13:00", "endTime": "17:30" },
        { "workType": "ETC", "workTarget": "라인 정기 점검 및 안전 수칙 확인", "startTime": "17:30", "endTime": "18:00" }
    ];
    dlt_grid.setJSON(sampleData);
    scwin.fn_initGridRender();
};

/**
 * DB에서 가져온 JSON 데이터를 targetCodeMaster 데이터리스트에 setJSON 하고 그리드 적용
 * @param {Array} jsonData - DB에서 조회한 작업대상 마스터 코드 데이터 목록
 */
scwin.fn_setTargetCodeMasterJSON = function(jsonData) {
    if (!jsonData) return;

    // 1. WebSquare DataList에 setJSON 적용
    if (window.dlt_targetCodeMaster) {
        dlt_targetCodeMaster.setJSON(jsonData);
        scwin.targetCodeMaster = dlt_targetCodeMaster.getAllJSON();
    } else {
        scwin.targetCodeMaster = jsonData;
    }

    // 2. 그리드 각 행별 셀 아이템 목록 재구성
    scwin.fn_initGridRender();
};

/**
 * 작업대상 마스터 코드 DB 조회 Submission 완료 콜백 (sbm_getTargetCodeMaster)
 */
scwin.sbm_getTargetCodeMaster_submitdone = function(e) {
    // 수신된 DataList 데이터를 scwin.targetCodeMaster 변수에 세팅 후 그리드 갱신
    if (window.dlt_targetCodeMaster) {
        scwin.targetCodeMaster = dlt_targetCodeMaster.getAllJSON();
        scwin.fn_initGridRender();
    }
};

/**
 * 특정일 작업 불러오기 버튼 클릭 이벤트
 */
scwin.btn_importWork_onclick = function() {
    var searchDate = document.getElementById("searchDateInput") ? document.getElementById("searchDateInput").value : "2026-09-07";
    if (!searchDate) {
        searchDate = "2026-09-07";
    }
    scwin.fn_openImportModal(searchDate);
};

/**
 * 특정일 작업내용 선택 모달 팝업 열기
 */
scwin.fn_openImportModal = function(searchDate) {
    var modal = document.getElementById("importModal");
    var modalTitleDate = document.getElementById("modalTitleDate");
    var modalTableBody = document.getElementById("importModalTableBody");

    if (!modal || !modalTableBody) return;

    modalTitleDate.innerText = "(" + searchDate + ")";
    modalTableBody.innerHTML = "";

    var list = scwin.workHistoryData[searchDate] || scwin.workHistoryData["2026-09-07"];

    if (!list || list.length === 0) {
        modalTableBody.innerHTML = '<tr><td colspan="5" style="text-align:center; color:#94a3b8; padding: 20px;">해당 일자에 조회된 작업내용이 없습니다.</td></tr>';
    } else {
        for (var i = 0; i < list.length; i++) {
            var item = list[i];
            var tr = document.createElement("tr");

            var targetColFormatted = scwin.fn_formatTargetText(item.workType, item.workTarget);

            var workTypeLabel = item.workType === 'EQ' ? '설비(EQ)' : (item.workType === 'MAT' ? '자재(MAT)' : '기타(ETC)');

            tr.innerHTML = '<td><input type="checkbox" class="import-chk" data-index="' + i + '" checked /></td>'
                + '<td>' + workTypeLabel + '</td>'
                + '<td><div style="white-space:pre-wrap;">' + targetColFormatted + '</div></td>'
                + '<td>' + item.startTime + ' ~ ' + item.endTime + '</td>'
                + '<td>' + (item.remark || '-') + '</td>';

            modalTableBody.appendChild(tr);
        }
    }

    modal.style.display = "flex";
};

/**
 * 작업대상 코드에 따른 label 포맷터 헬퍼
 */
scwin.fn_formatTargetText = function(workType, workTargetStr) {
    if (!workTargetStr) return "";
    if (workType !== "EQ" && workType !== "MAT") return workTargetStr;

    var masterList = (scwin.targetCodeMaster || []).filter(function(item) {
        return item.workType === workType;
    });
    var masterMap = {};
    for (var i = 0; i < masterList.length; i++) {
        masterMap[masterList[i].id] = masterList[i].name;
    }
    var valArr = workTargetStr.split(",");
    var resultArr = [];
    for (var j = 0; j < valArr.length; j++) {
        var val = valArr[j].trim();
        if (val) {
            resultArr.push(val + " (" + (masterMap[val] || val) + ")");
        }
    }
    return resultArr.join("\n");
};

/**
 * 모달 닫기
 */
scwin.fn_closeImportModal = function() {
    var modal = document.getElementById("importModal");
    if (modal) modal.style.display = "none";
};

/**
 * 선택한 특정일 작업내용 그리드에 적용(불러오기)
 */
scwin.fn_applyImportedWork = function() {
    var searchDate = document.getElementById("modalTitleDate").innerText.replace(/[()]/g, "");
    var list = scwin.workHistoryData[searchDate] || scwin.workHistoryData["2026-09-07"];
    var checkboxes = document.querySelectorAll(".import-chk:checked");

    if (checkboxes.length === 0) {
        alert("불러올 작업 항목을 선택해주세요.");
        return;
    }

    for (var i = 0; i < checkboxes.length; i++) {
        var idx = parseInt(checkboxes[i].getAttribute("data-index"), 10);
        var item = list[idx];

        // DataList에 새로운 행 추가
        var newRowIndex = dlt_grid.insertRow();
        dlt_grid.setCellData(newRowIndex, "workType", item.workType);
        dlt_grid.setCellData(newRowIndex, "workTarget", item.workTarget);
        dlt_grid.setCellData(newRowIndex, "startTime", item.startTime);
        dlt_grid.setCellData(newRowIndex, "endTime", item.endTime);
    }

    // 각 행별 checkcombobox 셀 아이템 목록 동적 초기화 및 정렬 적용
    scwin.fn_initGridRender();
    scwin.fn_closeImportModal();
};

/**
 * 그리드 데이터 로드 후 각 행별 checkcombobox 셀 아이템 목록 동적 초기화
 */
scwin.fn_initGridRender = function() {
    var rowCount = dlt_grid.getRowCount();
    for (var i = 0; i < rowCount; i++) {
        var workType = dlt_grid.getCellData(i, "workType");
        var workTarget = dlt_grid.getCellData(i, "workTarget");
        scwin.refreshTargetItemList(i, workType, workTarget);
    }
};

/**
 * 그리드 셀 변경 이벤트 (onviewchange)
 */
scwin.grd_workList_onviewchange = function(info) {
    var rowIndex = info.rowIndex;
    var colId = info.colID;
    var newValue = info.newValue;

    // 1. 작업구분 변경 시 -> 작업대상 초기화 및 드롭다운 목록 재구성
    if (colId === "workType") {
        var targetColIndex = grd_workList.getColumnIndex("workTarget");
        grd_workList.setCellData(rowIndex, targetColIndex, "");
        scwin.refreshTargetItemList(rowIndex, newValue, "");
    }

    // 2. 작업대상 선택 변경 시 -> 체크된 항목 최상단 재정렬
    if (colId === "workTarget") {
        var currentWorkType = dlt_grid.getCellData(rowIndex, "workType");
        scwin.refreshTargetItemList(rowIndex, currentWorkType, newValue);
    }
};

/**
 * 선택/체크된 항목을 상단으로 정렬하여 setCellItemList 적용 (EQ/MAT가 아닌 경우 text 모드)
 */
scwin.refreshTargetItemList = function(rowIndex, workType, selectedValuesStr) {
    var targetColIndex = grd_workList.getColumnIndex("workTarget");

    // EQ, MAT가 아닌 경우 -> 일반 text 입력 모드로 전환
    if (workType !== "EQ" && workType !== "MAT") {
        grd_workList.setCellInputType(rowIndex, targetColIndex, "text");
        return;
    }

    // EQ, MAT인 경우 -> checkcombobox 입력 모드로 전환
    grd_workList.setCellInputType(rowIndex, targetColIndex, "checkcombobox");

    var masterList = (scwin.targetCodeMaster || []).filter(function(item) {
        return item.workType === workType;
    });

    if (masterList.length === 0) {
        scwin.fn_setCellItemList(rowIndex, targetColIndex, []);
        return;
    }

    var selectedArr = selectedValuesStr ? selectedValuesStr.split(",") : [];
    var selectedSet = {};
    for (var i = 0; i < selectedArr.length; i++) {
        var trimmed = selectedArr[i].trim();
        if (trimmed) {
            selectedSet[trimmed] = true;
        }
    }

    // 체크된 항목 우선 정렬 (Checked 항목 -> Unchecked 항목)
    var sortedList = masterList.slice().sort(function(a, b) {
        var aChecked = selectedSet[a.id] ? 1 : 0;
        var bChecked = selectedSet[b.id] ? 1 : 0;
        return bChecked - aChecked;
    });

    // WebSquare setCellItemList용 배열 구조 생성 [{ label, value }]
    var itemList = [];
    for (var j = 0; j < sortedList.length; j++) {
        var item = sortedList[j];
        itemList.push({
            label: item.id + " (" + item.name + ")",
            value: item.id
        });
    }

    // 안전하게 셀 아이템 리스트 설정 (setCellItemList가 없을 경우 폴백)
    scwin.fn_setCellItemList(rowIndex, targetColIndex, itemList);
};

/**
 * GridView setCellItemList 방어적 헬퍼 (WebSquare 4/5 호환)
 */
scwin.fn_setCellItemList = function(rowIndex, colIndex, itemList) {
    if (typeof grd_workList.setCellItemList === "function") {
        grd_workList.setCellItemList(rowIndex, colIndex, itemList);
    } else if (typeof grd_workList.setCellItem === "function") {
        // WebSquare 4 호환 셀 아이템 세팅 API
        grd_workList.setCellItem(rowIndex, colIndex, itemList);
    } else if (typeof grd_workList.setColumnNodeSet === "function") {
        // WebSquare 4/5 컬럼 NodeSet 세팅 API
        grd_workList.setColumnNodeSet(colIndex, itemList, "label", "value");
    } else if (typeof grd_workList.setCellNodeSet === "function") {
        // WebSquare 5 셀 NodeSet 세팅 API
        grd_workList.setCellNodeSet(rowIndex, colIndex, itemList);
    }
};

/**
 * 작업대상 셀 커스텀 포맷터 (읽기 모드 포커스 아웃 시 멀티라인 출력)
 */
scwin.fn_workTargetFormatter = function(value, formattedValue, rowIndex, colIndex) {
    if (!value) return "";
    var workType = dlt_grid.getCellData(rowIndex, "workType");

    // EQ, MAT가 아닌 경우 -> 입력값 그대로 표시
    if (workType !== "EQ" && workType !== "MAT") {
        return value;
    }

    var masterList = (scwin.targetCodeMaster || []).filter(function(item) {
        return item.workType === workType;
    });
    var masterMap = {};
    for (var i = 0; i < masterList.length; i++) {
        masterMap[masterList[i].id] = masterList[i].name;
    }

    var valArr = value.split(",");
    var resultArr = [];
    for (var j = 0; j < valArr.length; j++) {
        var val = valArr[j].trim();
        if (val) {
            var name = masterMap[val] || val;
            resultArr.push(val + " (" + name + ")");
        }
    }

    // 줄바꿈 문자(\n)로 구분하여 반환
    return resultArr.join("\n");
};

/**
 * 조회 완료 콜백 (초기/조회 후 그리드 바인딩 복원)
 */
scwin.sbm_search_submitdone = function(e) {
    scwin.fn_initGridRender();
};
